use smallvec::{smallvec, SmallVec};

// up to 4 elements inline; the 5th spills to the heap
let mut v: SmallVec<[u8; 4]> = smallvec![1, 2, 3, 4];
assert!(!v.spilled());
v.push(5);                     // allocation happens here
assert!(v.spilled());          // SmallVec tracks which representation is live
let s: &[u8] = &v[..2];        // borrows die at the next mutation, as with Vec

