use arrayvec::ArrayVec;

let mut v: ArrayVec<u8, 4> = ArrayVec::new();
v.push(1); v.push(2); v.push(3); v.push(4);
assert!(v.is_full());
assert!(v.try_push(5).is_err());   // CapacityError: no heap, no growth
assert_eq!(v.len(), 4);            // the failed element was dropped
